-- data/demo-backing.sql — GENERATED by scripts/build-demo-backing.mjs
--
-- Demonstration backing history. Every contender total is the exact sum of
-- the bids beneath it, and every fan total the exact sum of that backer's
-- bids — bids and fan_totals are public, so the history has to add up.
--
-- The funding top-ups are recorded with provider 'test'. This belongs to a
-- build with DEMO_MODE on, which refuses every payment rail at the server.
--
-- Re-runnable: the seeded accounts share a fixed id prefix and are cleared
-- first, so this replaces its own data and leaves real backers alone.
--
-- Run AFTER data/top-100-battles.sql.

begin;

-- Clear a previous run. Seeded ids only.
delete from bids       where user_id::text like 'de110000-%';
delete from fan_totals where user_id::text like 'de110000-%';
delete from topups     where user_id::text like 'de110000-%';
delete from users      where id::text      like 'de110000-%';

-- ── Backers ──────────────────────────────────────────────────────────

-- ── What funded them ─────────────────────────────────────────────────
select id, balance_cents + total_spent_cents, balance_cents + total_spent_cents,
       'confirmed', 'test', 'demo-' || id, created_at
  from users where id::text like 'de110000-%' and balance_cents + total_spent_cents > 0;

-- ── Individual backings ──────────────────────────────────────────────

-- ── Per-backer totals ────────────────────────────────────────────────
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
