  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;
  on conflict (person_id,user_id) do update set total_cents = excluded.total_cents;

-- ── Contender totals ─────────────────────────────────────────────────
-- Derived from the bids rather than written separately, so the two cannot
-- disagree. first_backed_at comes from the earliest bid, which is also what
-- breaks ties on the board.
update people p set total_cents = x.total, first_backed_at = x.first
  from (select person_id, sum(amount_cents)::int total, min(created_at) first
          from bids group by person_id) x
 where x.person_id = p.id;

commit;

